const baseUrl = "https://wiking.intra.camdata.de";
const headers = {
  "Authorization": `Token ${getBookstackToken()}`,
  "Accept": "application/json"
};

async function searchBookstack(query, count = 20) {
  const url = `${baseUrl}/api/search?query=${encodeURIComponent(query)}&count=${count}`;
  const res = await fetch(url, { headers });
  if (!res.ok) return [];
  const data = await res.json();
  return data.data || [];
}

async function getPageMarkdown(id) {
  const url = `${baseUrl}/api/pages/${id}/export/markdown`;
  const res = await fetch(url, { headers });
  if (!res.ok) return null;
  const text = await res.text();
  return text;
}

async function getBook(id) {
  const url = `${baseUrl}/api/books/${id}`;
  const res = await fetch(url, { headers });
  if (!res.ok) return null;
  return await res.json();
}

// 1. Volltext-Suche nach LMS-Alternativen
let results = await searchBookstack("LMS Alternative Moodle", 20);

// Falls wenige Treffer, erweitern
if (results.length < 3) {
  const more = await searchBookstack("Schulungsplattform", 20);
  results = [...results, ...more];
}

if (results.length < 3) {
  const more2 = await searchBookstack("Moodle", 20);
  results = [...results, ...more2];
}

// Deduplizieren nach ID
const seen = new Set();
const unique = results.filter(r => {
  const key = `${r.type}-${r.id}`;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

// Seiten-Export für die relevantesten Treffer holen (max 5)
const pages = [];
for (const r of unique.slice(0, 8)) {
  if (r.type === "page") {
    const md = await getPageMarkdown(r.id);
    if (md) {
      // Zusammenfassen: ersten 2000 Zeichen
      const summary = md.length > 2000 ? md.substring(0, 2000) + "\n\n[... gekürzt]" : md;
      pages.push({ name: r.name, book: r.book?.name || "—", content: summary });
    }
  } else if (r.type === "book") {
    const book = await getBook(r.id);
    if (book && book.contents) {
      const chapterList = book.contents
        .map(c => `- **${c.name}** (${c.type})`)
        .join("\n");
      pages.push({ name: r.name, book: "Buch", content: `Buchinhalt:\n${chapterList}` });
    }
  } else {
    // chapter or other: preview als Fallback
    const preview = r.preview_html ? r.preview_html.replace(/<[^>]+>/g, "").substring(0, 500) : "";
    pages.push({ name: r.name, book: r.book?.name || "—", content: preview });
  }
}

// Ergebnis als Markdown zusammenbauen
let output = "## Recherche: LMS-Alternativen zu Moodle (BookStack-Wiki)\n\n";

if (pages.length === 0) {
  output += "Keine relevanten Einträge im Wiki gefunden.\n";
} else {
  output += `**${pages.length} relevante Treffer gefunden:**\n\n`;
  for (const p of pages) {
    output += `### ${p.name}\n`;
    output += `*Buch: ${p.book}*\n\n`;
    output += `${p.content}\n\n---\n\n`;
  }
}

return output;
```

